using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;
using ShipmentTracker.Data.Entities;

namespace ShipmentTracker.Services;

public static class ShipmentEndpoints
{
    private static int _trackingCounter = 100005;

    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        // All shipments — dispatchers only
        group.MapGet("/", [Authorize(Roles = "Dispatcher")] async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAtUtc)
                .ToListAsync();
            return Results.Ok(shipments.Select(ToDto));
        });

        // Track by tracking number — any authenticated user
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(ToDto(shipment));
        });

        // My shipments — returns shipments matching the caller's email
        group.MapGet("/mine", async (ClaimsPrincipal user, ApplicationDbContext db) =>
        {
            var email = user.FindFirstValue(ClaimTypes.Email);
            if (string.IsNullOrEmpty(email))
                return Results.Ok(Array.Empty<ShipmentDto>());

            var shipments = await db.Shipments
                .Where(s => s.CustomerEmail == email)
                .OrderByDescending(s => s.CreatedAtUtc)
                .ToListAsync();
            return Results.Ok(shipments.Select(ToDto));
        });

        // Create shipment — dispatchers only
        group.MapPost("/", [Authorize(Roles = "Dispatcher")] async (CreateShipmentRequest req, ApplicationDbContext db) =>
        {
            var trackingNum = $"TRK-{Interlocked.Increment(ref _trackingCounter):D6}";
            var shipment = new Shipment
            {
                TrackingNumber = trackingNum,
                Origin = req.Origin,
                Destination = req.Destination,
                Status = (int)ShipmentStatus.Pending,
                CreatedAtUtc = DateTime.UtcNow,
                EstimatedDeliveryUtc = req.EstimatedDeliveryUtc,
                CustomerEmail = req.CustomerEmail,
                Description = req.Description
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"api/shipments/track/{shipment.TrackingNumber}", ToDto(shipment));
        });

        // Update status — dispatchers only
        group.MapPut("/{id:int}/status", [Authorize(Roles = "Dispatcher")] async (int id, UpdateShipmentStatusRequest req, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null)
                return Results.NotFound();

            shipment.Status = (int)req.NewStatus;
            await db.SaveChangesAsync();
            return Results.NoContent();
        });
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        CreatedAtUtc = s.CreatedAtUtc,
        EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description
    };
}

