+            return Results.Ok(shipments.Select(ToDto));
+        });
+
+        // Create shipment — dispatchers only
+        group.MapPost("/", [Authorize(Roles = "Dispatcher")] async (CreateShipmentRequest req, ApplicationDbContext db) =>
+        {
+            var trackingNum = $"TRK-{Interlocked.Increment(ref _trackingCounter):D6}";
+            var shipment = new Shipment
+            {
+                TrackingNumber = trackingNum,
+                Origin = req.Origin,
+                Destination = req.Destination,
