using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side implementation that queries the database directly.
/// Used during SSR (before WebAssembly takes over).
/// </summary>
public class ShipmentServerService(ApplicationDbContext db, IHttpContextAccessor httpContextAccessor) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.CreatedAtUtc)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var s = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return s is null ? null : ToDto(s);
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        var email = httpContextAccessor.HttpContext?.User.FindFirst(System.Security.Claims.ClaimTypes.Email)?.Value;
        if (string.IsNullOrEmpty(email))
            return [];

        return await db.Shipments
            .Where(s => s.CustomerEmail == email)
            .OrderByDescending(s => s.CreatedAtUtc)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentRequest request)
    {
        var entity = new Data.Entities.Shipment
        {
            TrackingNumber = $"TRK-{Random.Shared.Next(100000, 999999)}",
            Origin = request.Origin,
            Destination = request.Destination,
            Status = (int)ShipmentStatus.Pending,
            CreatedAtUtc = DateTime.UtcNow,
            EstimatedDeliveryUtc = request.EstimatedDeliveryUtc,
            CustomerEmail = request.CustomerEmail,
            Description = request.Description
        };
        db.Shipments.Add(entity);
        await db.SaveChangesAsync();
        return ToDto(entity);
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is not null)
        {
            entity.Status = (int)newStatus;
            await db.SaveChangesAsync();
        }
    }

    private static ShipmentDto ToDto(Data.Entities.Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        CreatedAtUtc = s.CreatedAtUtc,
        EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description
    };
}

