arguments.file_text:
@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2 class="mb-4">📦 Dispatcher Dashboard</h2>

<div class="mb-3">
    <button class="btn btn-primary" @onclick="ToggleCreateForm">
        @(showCreateForm ? "Cancel" : "➕ New Shipment")
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="createShipment">
                <DataAnnotationsValidator />
                <div class="row g-3">
                    <div class="col-md-6">
                        <label class="form-label">Origin</label>
                        <InputText class="form-control" @bind-Value="newShipment.Origin" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Destination</label>
                        <InputText class="form-control" @bind-Value="newShipment.Destination" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Customer Email</label>
                        <InputText class="form-control" @bind-Value="newShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Estimated Delivery (UTC)</label>
                        <InputDate class="form-control" @bind-Value="estimatedDelivery" />
                    </div>
                    <div class="col-12">
                        <label class="form-label">Description</label>
                        <InputText class="form-control" @bind-Value="newShipment.Description" />
                    </div>
                    <div class="col-12">
                        <button type="submit" class="btn btn-success" disabled="@isCreating">
                            @(isCreating ? "Creating..." : "Create Shipment")
                        </button>
                    </div>
                </div>
            </EditForm>
        </div>
    </div>
}

@if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by tracking #, destination, or status..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Customer</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @StatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.CustomerEmail</td>
                        <td>@(s.EstimatedDeliveryUtc?.ToString("yyyy-MM-dd") ?? "—")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                            {
                                <select class="form-select form-select-sm d-inline-block w-auto"
                                        @onchange="e => UpdateStatus(s, e)">
                                    <option value="">Change status...</option>
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        if (status != s.Status)
                                        {
                                            <option value="@((int)status)">@status</option>
                                        }
                                    }
                                </select>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private string? errorMessage;
    private bool showCreateForm;
    private bool isCreating;
    private CreateShipmentRequest newShipment = new();
    private DateTime? estimatedDelivery;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        string.IsNullOrWhiteSpace(filterText)
            ? shipments!
            : shipments!.Where(s =>
                s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                s.Status.ToString().Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
    }

    private void ToggleCreateForm() => showCreateForm = !showCreateForm;

    private async Task CreateShipment()
    {
        isCreating = true;
        errorMessage = null;
        try
        {
            newShipment.EstimatedDeliveryUtc = estimatedDelivery.HasValue
