@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2 class="mb-4">🔍 Track a Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-100001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@isSearching">
                @(isSearching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (searched && shipment is null && errorMessage is null)
{
    <div class="alert alert-info">No shipment found with that tracking number.</div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@shipment.TrackingNumber</h5>
            <span class="badge @StatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                        <dt>Description</dt>
                        <dd>@(shipment.Description ?? "—")</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Created</dt>
                        <dd>@shipment.CreatedAtUtc.ToString("yyyy-MM-dd HH:mm") UTC</dd>
                        <dt>Estimated Delivery</dt>
                        <dd>
                            @if (shipment.EstimatedDeliveryUtc.HasValue)
                            {
                                <span>@shipment.EstimatedDeliveryUtc.Value.ToString("yyyy-MM-dd HH:mm") UTC</span>
                                @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Cancelled)
                                {
                                    var daysLeft = (shipment.EstimatedDeliveryUtc.Value - DateTime.UtcNow).Days;
                                    <br />
                                    <small class="text-muted">
                                        @(daysLeft > 0 ? $"{daysLeft} day(s) from now" : daysLeft == 0 ? "Today" : "Overdue")
                                    </small>
                                }
                            }
                            else
                            {
                                <span>—</span>
                            }
                        </dd>
                    </dl>
                </div>
            </div>

            <!-- Progress bar -->
            <div class="mt-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @ProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @ProgressPercent(shipment.Status)%"
                         aria-valuenow="@ProgressPercent(shipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @shipment.Status
                    </div>
                </div>
            </div>
        </div>
    </div>
}

<hr class="my-4" />

<h4>My Shipments</h4>
@if (myShipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (myShipments.Count == 0)
{
    <p class="text-muted">No shipments associated with your account.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in myShipments)
                {
                    <tr>
                        <td>@s.TrackingNumber</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @StatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@(s.EstimatedDeliveryUtc?.ToString("yyyy-MM-dd") ?? "—")</td>
                        <td>
                            <button class="btn btn-sm btn-outline-primary"
                                    @onclick="() => TrackShipment(s.TrackingNumber)">
                                View
                            </button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private ShipmentDto? shipment;
    private List<ShipmentDto>? myShipments;
    private string? errorMessage;
    private bool isSearching;
    private bool searched;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            myShipments = await ShipmentService.GetMyShipmentsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load your shipments: {ex.Message}";
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        errorMessage = null;
        searched = true;
        shipment = null;

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        }
        catch (Exception ex)
        {
            errorMessage = $"Search failed: {ex.Message}";
        }
        finally
        {
            isSearching = false;
        }
    }

    private async Task TrackShipment(string tracking)
    {
        trackingNumber = tracking;
        await Search();
    }

    private static string StatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string ProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Cancelled => "bg-danger",
        ShipmentStatus.Delivered => "bg-success",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private static int ProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

